import React, { useState } from 'react';
import Avatar from '@material-ui/core/Avatar';
import ChevronRightIcon from '@material-ui/icons/ChevronRight';
import NotificationsActiveIcon from '@material-ui/icons/NotificationsActive';
import AnnouncementIcon from '@material-ui/icons/Announcement';
import VideoCallIcon from '@material-ui/icons/VideoCall';
import AssignmentTurnedInIcon from '@material-ui/icons/AssignmentTurnedIn';
import EventIcon from '@material-ui/icons/Event';
import WbSunnyIcon from '@material-ui/icons/WbSunny';
import moment from 'moment';
import colors from 'config/colors';
import { circularLink, eventOrHolidayLink, examLink, goTo, noticeboardLink } from './dashboardLinks';

const SHOWN = 3;

// The words of a notice or circular as a short plain preview (the body can carry line breaks and links).
const preview = text =>
  String(text || '')
    .replace(/\s+/g, ' ')
    .trim();

const meetingUrl = raw => {
  const url = String(raw || '');
  if (!url.includes('http')) return `https://${url}`;
  if (!url.includes('https')) return url.replace('http', 'https');
  return url;
};

const formatMeeting = item =>
  `${moment(item?.meetupDate).format('MMM D, YYYY')} · ${moment(item?.meetupStartTime).format('hh:mm A')} – ${moment(
    item?.meetupEndTime
  ).format('hh:mm A')}`;

// Every kind of upcoming item as one row: what it is called, a line under it, when, where a click goes, and what "View all" opens.
// `external` is a link that leaves the app (the online class).
const KINDS = {
  circular: {
    icon: NotificationsActiveIcon,
    color: '#e53935',
    all: '/admin/circulars',
    row: item => ({
      title: item.subject || preview(item.content),
      line: item.subject ? preview(item.content) : '',
      when: moment(new Date(item.creationDateTime)).format('MMM D, YYYY'),
      url: circularLink(item),
    }),
  },
  noticeboard: {
    icon: AnnouncementIcon,
    color: '#00897b',
    all: '/admin/notice-board',
    row: item => ({
      title: item.subject || preview(item.content),
      line: item.subject ? preview(item.content) : '',
      when: moment(new Date(item.creationDateTime)).format('MMM D, YYYY'),
      url: noticeboardLink(item),
    }),
  },
  meeting: {
    icon: VideoCallIcon,
    color: '#5e35b1',
    row: item => ({
      title: item.title,
      line: preview(item.description),
      when: formatMeeting(item),
      url: meetingUrl(item.meetupUrl),
      external: true,
    }),
  },
  exam: {
    icon: AssignmentTurnedInIcon,
    color: '#fb8c00',
    all: '/admin/employee-activities?tab=exams-marks',
    row: item => ({
      title: item.examTitle,
      line: item.subjectTotalMark !== undefined ? `Total mark: ${item.subjectTotalMark}` : '',
      when: `${moment(new Date(item.startDate)).format('MMM D')} – ${moment(new Date(item.endDate)).format(
        'MMM D, YYYY'
      )}`,
      url: examLink(item),
    }),
  },
  event: {
    icon: EventIcon,
    color: '#43a047',
    all: '/admin/events-holidays?type=EVENT',
    row: item => ({
      title: item.title,
      line: preview(item.description),
      when: moment(new Date(item.startDateTime)).format('MMM D, YYYY'),
      url: eventOrHolidayLink(item, 'event'),
    }),
  },
  holiday: {
    icon: WbSunnyIcon,
    color: '#f9a825',
    all: '/admin/events-holidays?type=HOLIDAY',
    row: item => ({
      title: item.title,
      line: preview(item.description),
      when: moment(new Date(item.startDateTime)).format('MMM D, YYYY'),
      url: eventOrHolidayLink(item, 'holiday'),
    }),
  },
};

const rowStyle = {
  display: 'flex',
  alignItems: 'center',
  gap: 12,
  padding: '10px 14px',
  color: 'inherit',
  textDecoration: 'none',
  borderBottom: '1px solid #f0edf5',
};

// The latest few upcoming items of one kind as a stacked list: the whole row opens the item. Replaces the one-at-a-time carousel, so
// everything coming up is visible at a glance; more than a few folds behind "View all" (the page of that kind, or "Show all" for
// the online classes, which have no page of their own).
const UpcomingList = ({ carouselType, carouselList, history, emptyText = 'Nothing coming up' }) => {
  const kind = KINDS[carouselType];
  const [expanded, setExpanded] = useState(false);
  if (!kind) return null;
  if (!carouselList?.length) {
    return <div className="rui-upcoming rui-upcoming-empty">{emptyText}</div>;
  }
  const Icon = kind.icon;
  const shown = expanded ? carouselList : carouselList.slice(0, SHOWN);
  const more = carouselList.length - SHOWN;

  return (
    <div className="rui-upcoming">
      {shown.map((item, index) => {
        const row = kind.row(item);
        return (
          <a
            key={index}
            href={row.url}
            style={{ ...rowStyle, ...(index === shown.length - 1 && more <= 0 ? { borderBottom: 0 } : {}) }}
            className="rui-upcoming-row"
            {...(row.external ? { target: '_blank', rel: 'noreferrer' } : { onClick: goTo(history, row.url) })}>
            <Avatar style={{ backgroundColor: `${kind.color}1a`, color: kind.color, width: 36, height: 36 }}>
              <Icon style={{ fontSize: 19 }} />
            </Avatar>
            <div style={{ flex: 1, minWidth: 0 }}>
              <div className="rui-upcoming-title">{row.title}</div>
              {row.line && <div className="rui-upcoming-line">{row.line}</div>}
              <div className="rui-upcoming-when">{row.when}</div>
            </div>
            <ChevronRightIcon style={{ fontSize: 18, color: '#b8b2c8' }} />
          </a>
        );
      })}
      {more > 0 &&
        (kind.all ? (
          <a
            className="rui-upcoming-more"
            href={kind.all}
            style={{ color: colors.accent }}
            onClick={goTo(history, kind.all)}>
            View all ({carouselList.length})
            <ChevronRightIcon style={{ fontSize: 18 }} />
          </a>
        ) : (
          <button
            type="button"
            className="rui-upcoming-more"
            style={{ color: colors.accent }}
            onClick={() => setExpanded(open => !open)}>
            {expanded ? 'Show less' : `Show all (${carouselList.length})`}
          </button>
        ))}
    </div>
  );
};

export default UpcomingList;
