import React, { useEffect, useState } from 'react';
import { useSelector } from 'react-redux';
import { useHistory } from 'react-router-dom';
import CustomButton from 'components/CustomButton';
import colors from 'config/colors';
import { fetchSetupStatusApi } from 'actions/admin/onboarding';
import { getGlobalSchoolUtils } from 'utils/commonFunc';
import constants from 'config/constants';

// For a brand-new school (no classes yet, or no admin login yet) the super admin sees a card on the Dashboard pointing to the school's
// setup (opened from the Schools page). It never blocks anything: an old school with data shows nothing. Only the super admin gets it:
// setting a school up is the super admin's job, and the school's own admins never see this card.
const SetupPrompt = () => {
  const history = useHistory();
  const token = useSelector(state => state.auth.loggedUserToken);
  const schoolId = getGlobalSchoolUtils()?.schoolId;
  const isSuperAdmin = useSelector(state => state.auth.loggedUserRole) === constants.roles.SA;
  const [status, setStatus] = useState(null);

  useEffect(() => {
    if (!token || !schoolId || !isSuperAdmin) return undefined;
    let cancelled = false;
    fetchSetupStatusApi({ token, schoolId })
      .then(result => !cancelled && setStatus(result))
      .catch(() => !cancelled && setStatus(null));
    return () => {
      cancelled = true;
    };
  }, [token, schoolId, isSuperAdmin]);

  if (!isSuperAdmin || !status || (status.initialized && status.setupDone)) return null;

  return (
    <div
      className="d-flex flex-wrap align-items-center justify-content-between"
      style={{
        gap: 12,
        padding: '12px 16px',
        marginBottom: 16,
        borderRadius: 14,
        background: '#fff4e0',
        border: '1px solid #f5b84a',
      }}>
      <div style={{ fontSize: 13 }}>
        <b style={{ color: colors.accent }}>This school&apos;s setup is not done yet.</b>{' '}
        {status.setupDone
          ? 'Next: create the batch, classes and subjects.'
          : 'Start by creating the school admin login.'}{' '}
        You can leave this and come back any time from Schools.
      </div>
      <CustomButton
        size="small"
        name="Start school setup"
        onClick={() =>
          history.push(`/admin/schools/${schoolId}/setup`, { schoolName: getGlobalSchoolUtils()?.schoolName })
        }
      />
    </div>
  );
};

export default SetupPrompt;
